//! 全彩 Emoji 向量渲染模組 (Twemoji / SVG 高解析度彩色向量引擎)

#[derive(Debug, Clone, PartialEq)]
pub enum TextOrEmoji<'a> {
    Text(&'a str),
    Emoji(&'a str, &'static str),
}

