/// 判斷單一字符是否為常見 Emoji
pub fn is_emoji_char(c: char) -> bool {
    let u = c as u32;
    matches!(
        u,
        0x1F300..=0x1F9FF
            | 0x1FA00..=0x1FAFF
            | 0x1F1E0..=0x1F1FF
            | 0x1F600..=0x1F64F
            | 0x1F680..=0x1F6FF
            | 0x2600..=0x27BF
            | 0x2B05..=0x2B07
            | 0x2B50
            | 0x23F0..=0x23F3
            | 0x2139
    )
}

/// 將任意字串依序拆分為「純文字片段」與「全彩 Emoji 片段」
pub fn split_text_emojis<'a>(text: &'a str) -> Vec<TextOrEmoji<'a>> {
    let mut result = Vec::new();
    let mut current_text_start = 0;
    let mut char_indices = text.char_indices().peekable();

    while let Some((idx, c)) = char_indices.next() {
        if is_emoji_char(c) {
            let emoji_start = idx;
            let mut emoji_end = idx + c.len_utf8();

            // 檢查後續是否有變體選擇器或連字號
            while let Some(&(next_idx, next_c)) = char_indices.peek() {
                if next_c == '\u{FE0F}' || next_c == '\u{FE0E}' || next_c == '\u{200D}' {
                    char_indices.next();
                    emoji_end = next_idx + next_c.len_utf8();
                } else {
                    break;
                }
            }

            let emoji_slice = &text[emoji_start..emoji_end];
            if let Some(svg) = get_emoji_svg(emoji_slice) {
                if emoji_start > current_text_start {
                    result.push(TextOrEmoji::Text(&text[current_text_start..emoji_start]));
                }
                result.push(TextOrEmoji::Emoji(emoji_slice, svg));
                current_text_start = emoji_end;
            }
        }
    }

    if current_text_start < text.len() {
        result.push(TextOrEmoji::Text(&text[current_text_start..]));
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_get_emoji_svg() {
        assert!(get_emoji_svg("⚡").is_some());
        assert!(get_emoji_svg("🧠").is_some());
        assert!(get_emoji_svg("📽").is_some());
        assert!(get_emoji_svg("✏").is_some());
        assert!(get_emoji_svg("💾").is_some());
        assert!(get_emoji_svg("⚙").is_some());
        assert!(get_emoji_svg("🔍").is_some());
        assert!(get_emoji_svg("✨").is_some());
    }

    #[test]
    fn test_split_text_emojis() {
        let text = "• ⚡ 原生極速渲染：基於 egui";
        let segments = split_text_emojis(text);
        assert_eq!(segments.len(), 3);
        assert_eq!(segments[0], TextOrEmoji::Text("• "));
        match segments[1] {
            TextOrEmoji::Emoji("⚡", _) => {}
            _ => panic!("Expected emoji"),
        }
        assert_eq!(segments[2], TextOrEmoji::Text(" 原生極速渲染：基於 egui"));
    }
}
